package com.example.ragpoc.chat;

/**
 * Wall-clock timings for one answer, in milliseconds.
 *
 * <p>Retrieval's own stage timings live on the {@code RetrievalTrace}; these are
 * the parts around it, so the panel can show where a slow answer spent its time.
 *
 * @param retrievalMillis everything retrieval did, from the input guard to the
 *     assembled context
 * @param firstTokenMillis from the start of generation to the first streamed
 *     token; {@code 0} when there was no stream to observe, either because the
 *     answer was refused or because it was generated by the non-streaming
 *     fallback
 * @param generationMillis the model call, first token to last
 * @param totalMillis the whole request, retrieval start to final token
 * @param refused true when the relevance gate refused and no model was called
 */
public record ChatTimings(
    long retrievalMillis,
    long firstTokenMillis,
    long generationMillis,
    long totalMillis,
    boolean refused) {}
